    /// The cataloged wire id (uppercase; `_X` suffix for
    /// parameterized errors).
    pub fn wire(self: Id) []const u8 {
        return entries[@intFromEnum(self)].wire;
    }

    /// Human-oriented description; `{value}` marks the parameter.
    pub fn description(self: Id) []const u8 {
        return entries[@intFromEnum(self)].description;
    }

    /// Whether the wire form carries a numeric suffix
    /// (`FLOOD_WAIT_60`).
    pub fn parameterized(self: Id) bool {
        return entries[@intFromEnum(self)].parameterized;
    }
};

/// Number of cataloged error identifiers.
pub const count: usize = 889;

/// A classified `rpc_error` message.
pub const Classified = struct {
    id: Id,
    /// Numeric suffix of a parameterized id (`FLOOD_WAIT_60` -> 60).
    value: ?u32,
};

/// Maps a wire `rpc_error` message to its catalog entry: exact match
/// first, then a trailing `_<digits>` suffix is normalized to `_X`
/// (the digits become `value`). Returns null for unknown messages —
/// the raw string stays available in `RpcErrorInfo.message`.
pub fn classify(message: []const u8) ?Classified {
    if (lookup(message)) |id| return .{ .id = id, .value = null };
    const us = std.mem.lastIndexOfScalar(u8, message, '_') orelse return null;
    const digits = message[us + 1 ..];
    if (digits.len == 0 or digits.len > 9) return null;
    for (digits) |c| {
        if (c < '0' or c > '9') return null;
    }
    if (us + 2 > lookup_buf.len) return null;
    @memcpy(lookup_buf[0..us], message[0..us]);
    lookup_buf[us] = '_';
    lookup_buf[us + 1] = 'X';
    const id = lookup(lookup_buf[0 .. us + 2]) orelse return null;
    return .{ .id = id, .value = std.fmt.parseInt(u32, digits, 10) catch null };
}

const Entry = struct {
    wire: []const u8,
    description: []const u8,
    parameterized: bool,
};

