/// Scratch for `classify`'s normalized candidate: no catalog id is
/// longer than the longest wire id, so overlong messages (which
/// cannot match anything) are rejected instead of copied.
var lookup_buf: [37]u8 = undefined;

/// Binary search over `entries` (sorted by wire id).
fn lookup(message: []const u8) ?Id {
    var lo: usize = 0;
    var hi: usize = entries.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        switch (std.mem.order(u8, entries[mid].wire, message)) {
            .eq => {
                const id: Id = @enumFromInt(mid);
                return id;
            },
            .gt => hi = mid,
            .lt => lo = mid + 1,
        }
    }
    return null;
}
